import{_ as p,a0 as l,w as o,s as r,ao as c,I as t,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Kubernetes 集群中设置动态 NFS 配置 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubernetes 集群中设置动态 NFS 配置 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubernetes 集群中设置动态 NFS 配置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubernetes 集群中设置动态 NFS 配置 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster","title":"如何在 Kubernetes 集群中设置动态 NFS 配置","tag":"202307","desc":""},"relativePath":"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster.md","filePath":"[post].md"}'),d={name:"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster.md"};function h(u,s,g,b,k,m){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-kubernetes-集群中设置动态-nfs-配置" tabindex="-1">如何在 Kubernetes 集群中设置动态 NFS 配置 <a class="header-anchor" href="#如何在-kubernetes-集群中设置动态-nfs-配置" aria-label="Permalink to “如何在 Kubernetes 集群中设置动态 NFS 配置”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/28/222834togtruhoeuh3gtr1.jpg" alt=""></p><blockquote><p>在这篇文章中，我们将向你展示如何在 Kubernetes（k8s）集群中设置动态 NFS 配置。</p></blockquote><p>Kubernetes 中的动态 NFS 存储配置允许你按需自动为 Kubernetes 应用配置和管理 NFS（网络文件系统）卷。它允许创建持久卷（PV）和持久卷声明（PVC），而无需手动干预或预配置存储。</p><p>NFS 配置程序负责动态创建 PV 并将其绑定到 PVC。它与 NFS 服务器交互，为每个 PVC 创建目录或卷。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><ul><li>预装 Kubernetes 集群</li><li>具有 Kubernetes 集群管理员权限的普通用户</li><li>互联网连接</li></ul><p>事不宜迟，让我们深入探讨步骤：</p><h3 id="步骤-1、准备-nfs-服务器" tabindex="-1">步骤 1、准备 NFS 服务器 <a class="header-anchor" href="#步骤-1、准备-nfs-服务器" aria-label="Permalink to “步骤 1、准备 NFS 服务器”">​</a></h3><p>就我而言，我将在 Kubernetes 主节点（Ubuntu 22.04）上安装 NFS 服务器。登录主节点并运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install nfs-kernel-server -y</span></span></code></pre></div><p>创建以下文件夹并使用 NFS 共享它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /opt/dynamic-storage</span></span>
<span class="line"><span>$ sudo chown -R nobody:nogroup /opt/dynamic-storage</span></span>
<span class="line"><span>$ sudo chmod 777 /opt/dynamic-storage</span></span></code></pre></div><p>在 <code>/etc/exports</code> 文件中添加以下条目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/exports</span></span>
<span class="line"><span>/opt/dynamic-storage 192.168.1.0/24(rw,sync,no_subtree_check)</span></span></code></pre></div><p>保存并关闭文件。</p><p>注意：不要忘记更改导出文件中适合你的部署的网络。</p><p>要使上述更改生效，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo exportfs -a</span></span>
<span class="line"><span>$ sudo systemctl restart nfs-kernel-server</span></span>
<span class="line"><span>$ sudo systemctl status nfs-kernel-server</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/NFS-Service-Status-Kubernetes-Master-Ubuntu.png" alt="NFS-Service-Status-Kubernetes-Master-Ubuntu"></p><p>在工作节点上，使用以下 <code>apt</code> 命令安装 <code>nfs-common</code> 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install nfs-common -y</span></span></code></pre></div><h3 id="步骤-2、安装和配置-nfs-客户端配置程序" tabindex="-1">步骤 2、安装和配置 NFS 客户端配置程序 <a class="header-anchor" href="#步骤-2、安装和配置-nfs-客户端配置程序" aria-label="Permalink to “步骤 2、安装和配置 NFS 客户端配置程序”">​</a></h3><p>NFS 子目录外部配置程序在 Kubernetes 集群中部署 NFS 客户端配置程序。配置程序负责动态创建和管理由 NFS 存储支持的持久卷（PV）和持久卷声明（PVC）。</p><p>因此，要安装 NFS 子目录外部配置程序，首先使用以下命令集安装 <code>helm</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL -o get_helm.sh https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3</span></span>
<span class="line"><span>$ chmod 700 get_helm.sh</span></span>
<span class="line"><span>$ ./get_helm.sh</span></span></code></pre></div><p>运行以下命令来启用 <code>helm</code> 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo add nfs-subdir-external-provisioner https://kubernetes-sigs.github.io/nfs-subdir-external-provisioner</span></span></code></pre></div><p>使用以下 <code>helm</code> 命令部署配置程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm install -n nfs-provisioning --create-namespace nfs-subdir-external-provisioner nfs-subdir-external-provisioner/nfs-subdir-external-provisioner --set nfs.server=192.168.1.139 --set nfs.path=/opt/dynamic-storage</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/helm-install-nfs-provisioning-kubernetes-cluster.png" alt="helm-install-nfs-provisioning-kubernetes-cluster"></p><p>上面的 <code>helm</code> 命令将自动创建 <code>nfs-provisioning</code> 命名空间，并安装 NFS 配置程序的容器荚/部署、名称为 <code>nfs-client</code> 的存储类，并将创建所需的 rbac。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get all -n nfs-provisioning</span></span>
<span class="line"><span>$ kubectl get sc -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/kubectl-get-all-nfs-provisioning-kubernetes-cluster.png" alt="kubectl-get-all-nfs-provisioning-kubernetes-cluster"></p><p>完美，上面的输出确认了配置程序容器荚和存储类已成功创建。</p><h3 id="步骤-3、创建持久卷声明-pvc" tabindex="-1">步骤 3、创建持久卷声明（PVC） <a class="header-anchor" href="#步骤-3、创建持久卷声明-pvc" aria-label="Permalink to “步骤 3、创建持久卷声明（PVC）”">​</a></h3><p>让我们创建 PVC 来为你的容器荚或部署请求存储。PVC 将从存储类 <code>nfs-client</code> 请求特定数量的存储：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi demo-pvc.yml</span></span>
<span class="line"><span>kind: PersistentVolumeClaim</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: demo-claim</span></span>
<span class="line"><span>  namespace: nfs-provisioning</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  storageClassName: nfs-client</span></span>
<span class="line"><span>  accessModes:</span></span>
<span class="line"><span>    - ReadWriteMany</span></span>
<span class="line"><span>  resources:</span></span>
<span class="line"><span>    requests:</span></span>
<span class="line"><span>      storage: 10Mi</span></span></code></pre></div><p>保存并关闭文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/PVC-Yaml-Dynamic-NFS-Kubernetes.png" alt="PVC-Yaml-Dynamic-NFS-Kubernetes"></p><p>运行以下 <code>kubectl</code> 命令以使用上面创建的 YML 文件创建 PVC：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f demo-pvc.yml</span></span></code></pre></div><p>验证 PVC 和 PV 是否创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pv,pvc -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Verify-pv-pvc-dynamic-nfs-kubernetes-cluster.png" alt="Verify-pv-pvc-dynamic-nfs-kubernetes-cluster"></p><p>太好了，上面的输出表明 PV 和 PVC 创建成功。</p><h3 id="步骤-4、测试并验证动态-nfs-配置" tabindex="-1">步骤 4、测试并验证动态 NFS 配置 <a class="header-anchor" href="#步骤-4、测试并验证动态-nfs-配置" aria-label="Permalink to “步骤 4、测试并验证动态 NFS 配置”">​</a></h3><p>为了测试和验证动态 NFS 配置，请使用以下 YML 文件启动测试容器荚：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi test-pod.yml</span></span>
<span class="line"><span>kind: Pod</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: test-pod</span></span>
<span class="line"><span>  namespace: nfs-provisioning</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  containers:</span></span>
<span class="line"><span>  - name: test-pod</span></span>
<span class="line"><span>    image: busybox:latest</span></span>
<span class="line"><span>    command:</span></span>
<span class="line"><span>      - &quot;/bin/sh&quot;</span></span>
<span class="line"><span>    args:</span></span>
<span class="line"><span>      - &quot;-c&quot;</span></span>
<span class="line"><span>      - &quot;touch /mnt/SUCCESS &amp;&amp; sleep 600&quot;</span></span>
<span class="line"><span>    volumeMounts:</span></span>
<span class="line"><span>      - name: nfs-pvc</span></span>
<span class="line"><span>        mountPath: &quot;/mnt&quot;</span></span>
<span class="line"><span>  restartPolicy: &quot;Never&quot;</span></span>
<span class="line"><span>  volumes:</span></span>
<span class="line"><span>    - name: nfs-pvc</span></span>
<span class="line"><span>      persistentVolumeClaim:</span></span>
<span class="line"><span>        claimName: demo-claim</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Pod-Yml-Dynamic-NFS-kubernetes.png" alt="Pod-Yml-Dynamic-NFS-kubernetes"></p><p>使用以下 <code>kubectl</code> 命令部署容器荚：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f test-pod.yml</span></span></code></pre></div><p>验证 <code>test-pod</code> 的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pods -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Verify-Test-Pod-Using-NFS-Volume-Kubernetes.png" alt="Verify-Test-Pod-Using-NFS-Volume-Kubernetes"></p><p>登录到容器荚并验证 NFS 卷是否已安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl exec -it test-pod -n nfs-provisioning /bin/sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Access-Dynamic-NFS-Inside-Pod-Kubernetes.png" alt="Access-Dynamic-NFS-Inside-Pod-Kubernetes"></p><p>太棒了，上面容器荚的输出确认了动态 NFS 卷已安装且可访问。</p><p>最后删除容器荚和 PVC，查看 PV 是否自动删除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl delete -f test-pod.yml</span></span>
<span class="line"><span>$ kubectl delete -f demo-pvc.yml</span></span>
<span class="line"><span>$ kubectl get pv,pvc -n  nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Delete-Pod-PVC-Dynamic-NFS.png" alt="Delete-Pod-PVC-Dynamic-NFS"></p><p>这就是这篇文章的全部内容，希望对你有所帮助。请随时在下面的评论部分发表你的疑问和反馈。</p><p><em>（题图：MJ/75dae36f-ff68-4c63-81e8-281e2c239356）</em></p><hr>`,65)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.linuxtechi.com/dynamic-nfs-provisioning-kubernetes/"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.linuxtechi.com/dynamic-nfs-provisioning-kubernetes/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[e("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(n,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=p(d,[["render",h]]);export{v as __pageData,C as default};
